// ─── Users ────────────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
}

export type CreateUserBody = Omit<User, "id">;
export type UpdateUserBody = Partial<CreateUserBody>;

// ─── Projects ─────────────────────────────────────────────────────────────────

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type CreateProjectBody = Omit<Project, "id" | "memberIds">;
export type UpdateProjectBody = Partial<Omit<Project, "id" | "memberIds">>;

export interface AddMemberBody {
  userId: string;
}

// ─── Tasks ────────────────────────────────────────────────────────────────────

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export type CreateTaskBody = {
  title: string;
  description: string;
  projectId: string;
  assigneeId?: string | null;
};

export type UpdateTaskBody = Partial<{
  title: string;
  description: string;
}>;

export interface UpdateStatusBody {
  status: TaskStatus;
}

export interface AssignTaskBody {
  userId: string | null;
}

// Valid task status transitions
export const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in-progress"],
  "in-progress": ["done"],
  done: [],
};

// ─── Comments ─────────────────────────────────────────────────────────────────

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO timestamp
}

export type CreateCommentBody = {
  taskId: string;
  authorId: string;
  body: string;
};

// ─── Notifications ────────────────────────────────────────────────────────────

export type NotificationEvent = "task_assigned" | "comment_added" | "status_changed";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  event: NotificationEvent;
  read: boolean;
  createdAt: string; // ISO timestamp
}

// ─── HTTP helpers ─────────────────────────────────────────────────────────────

export interface ParsedRequest {
  method: string;
  pathname: string;
  segments: string[];
  query: Record<string, string>;
  body: unknown;
}

export interface RouteHandler {
  (req: ParsedRequest): Promise<RouteResponse>;
}

export interface RouteResponse {
  status: number;
  body: unknown;
}

import { randomUUID } from "crypto";
import type { User, Project, Task, Comment, Notification, NotificationEvent } from "./types.js";

// ─── In-memory collections ────────────────────────────────────────────────────

export const users = new Map<string, User>();
export const projects = new Map<string, Project>();
export const tasks = new Map<string, Task>();
export const comments = new Map<string, Comment>();
export const notifications = new Map<string, Notification>();

// ─── ID generation ────────────────────────────────────────────────────────────

export function newId(): string {
  return randomUUID();
}

// ─── Notification helpers ─────────────────────────────────────────────────────

export function createNotification(
  userId: string,
  message: string,
  event: NotificationEvent
): Notification {
  const notification: Notification = {
    id: newId(),
    userId,
    message,
    event,
    read: false,
    createdAt: new Date().toISOString(),
  };
  notifications.set(notification.id, notification);
  return notification;
}

/**
 * Notify all members of a project except the actor.
 */
export function notifyProjectMembers(
  projectId: string,
  actorId: string | null,
  message: string,
  event: NotificationEvent
): void {
  const project = projects.get(projectId);
  if (!project) return;
  for (const memberId of project.memberIds) {
    if (memberId !== actorId) {
      createNotification(memberId, message, event);
    }
  }
}

import type { RouteHandler, ParsedRequest, RouteResponse } from "./types.js";
import type { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";

// ─── Route entry ──────────────────────────────────────────────────────────────

interface Route {
  method: string;
  /** Pattern segments: plain strings or ":param" wildcards */
  pattern: string[];
  handler: RouteHandler;
}

// ─── Router ───────────────────────────────────────────────────────────────────

export class Router {
  private routes: Route[] = [];

  register(method: string, path: string, handler: RouteHandler): void {
    const pattern = path.split("/").filter(Boolean);
    this.routes.push({ method: method.toUpperCase(), pattern, handler });
  }

  get(path: string, handler: RouteHandler): void {
    this.register("GET", path, handler);
  }

  post(path: string, handler: RouteHandler): void {
    this.register("POST", path, handler);
  }

  put(path: string, handler: RouteHandler): void {
    this.register("PUT", path, handler);
  }

  delete(path: string, handler: RouteHandler): void {
    this.register("DELETE", path, handler);
  }

  // ─── Dispatch ──────────────────────────────────────────────────────────────

  async dispatch(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const baseUrl = `http://${req.headers.host ?? "localhost"}`;
    const parsedUrl = new URL(req.url ?? "/", baseUrl);
    const pathname = parsedUrl.pathname;
    const segments = pathname.split("/").filter(Boolean);
    const method = (req.method ?? "GET").toUpperCase();

    // Build query params
    const query: Record<string, string> = {};
    parsedUrl.searchParams.forEach((value, key) => {
      query[key] = value;
    });

    // Read body
    let body: unknown = null;
    if (method !== "GET" && method !== "DELETE") {
      body = await readBody(req);
    }

    const parsed: ParsedRequest = { method, pathname, segments, query, body };

    // Find matching route
    for (const route of this.routes) {
      if (route.method !== method) continue;
      const params = matchPattern(route.pattern, segments);
      if (params === null) continue;

      // Merge path params into parsed segments (already available via segments)
      // but also expose them in query for convenience
      Object.assign(parsed.query, params);

      try {
        const result: RouteResponse = await route.handler(parsed);
        sendJSON(res, result.status, result.body);
      } catch (err) {
        const message = err instanceof Error ? err.message : "Internal server error";
        sendJSON(res, 500, { error: message });
      }
      return;
    }

    sendJSON(res, 404, { error: "Route not found" });
  }
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns a map of param → value if the URL segments match the pattern,
 * or null if they don't match.
 */
function matchPattern(
  pattern: string[],
  segments: string[]
): Record<string, string> | null {
  if (pattern.length !== segments.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < pattern.length; i++) {
    const p = pattern[i];
    const s = segments[i];
    if (p.startsWith(":")) {
      params[p.slice(1)] = s;
    } else if (p !== s) {
      return null;
    }
  }
  return params;
}

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf-8").trim();
      if (!raw) {
        resolve(null);
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        resolve(null);
      }
    });
    req.on("error", reject);
  });
}

function sendJSON(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

import { users, newId } from "../store.js";
import type { RouteHandler, CreateUserBody, UpdateUserBody } from "../types.js";

// ─── GET /users ───────────────────────────────────────────────────────────────

export const listUsers: RouteHandler = async (_req) => {
  return { status: 200, body: Array.from(users.values()) };
};

// ─── POST /users ──────────────────────────────────────────────────────────────

export const createUser: RouteHandler = async (req) => {
  const data = req.body as CreateUserBody;

  if (!data || typeof data.name !== "string" || !data.name.trim()) {
    return { status: 400, body: { error: "name is required" } };
  }
  if (typeof data.email !== "string" || !data.email.trim()) {
    return { status: 400, body: { error: "email is required" } };
  }

  // Ensure email uniqueness
  const emailExists = Array.from(users.values()).some(
    (u) => u.email.toLowerCase() === data.email.toLowerCase()
  );
  if (emailExists) {
    return { status: 409, body: { error: "A user with that email already exists" } };
  }

  const user = { id: newId(), name: data.name.trim(), email: data.email.trim() };
  users.set(user.id, user);
  return { status: 201, body: user };
};

// ─── GET /users/:id ───────────────────────────────────────────────────────────

export const getUser: RouteHandler = async (req) => {
  const user = users.get(req.query["id"]);
  if (!user) return { status: 404, body: { error: "User not found" } };
  return { status: 200, body: user };
};

// ─── PUT /users/:id ───────────────────────────────────────────────────────────

export const updateUser: RouteHandler = async (req) => {
  const user = users.get(req.query["id"]);
  if (!user) return { status: 404, body: { error: "User not found" } };

  const data = req.body as UpdateUserBody;
  if (!data) return { status: 400, body: { error: "Request body is required" } };

  if (data.name !== undefined) {
    if (typeof data.name !== "string" || !data.name.trim()) {
      return { status: 400, body: { error: "name must be a non-empty string" } };
    }
    user.name = data.name.trim();
  }

  if (data.email !== undefined) {
    if (typeof data.email !== "string" || !data.email.trim()) {
      return { status: 400, body: { error: "email must be a non-empty string" } };
    }
    const emailExists = Array.from(users.values()).some(
      (u) => u.id !== user.id && u.email.toLowerCase() === data.email!.toLowerCase()
    );
    if (emailExists) {
      return { status: 409, body: { error: "A user with that email already exists" } };
    }
    user.email = data.email.trim();
  }

  users.set(user.id, user);
  return { status: 200, body: user };
};

// ─── DELETE /users/:id ────────────────────────────────────────────────────────

export const deleteUser: RouteHandler = async (req) => {
  const id = req.query["id"];
  if (!users.has(id)) return { status: 404, body: { error: "User not found" } };
  users.delete(id);
  return { status: 200, body: { message: "User deleted" } };
};

import { projects, users, newId } from "../store.js";
import type {
  RouteHandler,
  CreateProjectBody,
  UpdateProjectBody,
  AddMemberBody,
} from "../types.js";

// ─── GET /projects ────────────────────────────────────────────────────────────

export const listProjects: RouteHandler = async (_req) => {
  return { status: 200, body: Array.from(projects.values()) };
};

// ─── POST /projects ───────────────────────────────────────────────────────────

export const createProject: RouteHandler = async (req) => {
  const data = req.body as CreateProjectBody;

  if (!data || typeof data.name !== "string" || !data.name.trim()) {
    return { status: 400, body: { error: "name is required" } };
  }
  if (typeof data.description !== "string") {
    return { status: 400, body: { error: "description is required" } };
  }

  const project = {
    id: newId(),
    name: data.name.trim(),
    description: data.description.trim(),
    memberIds: [],
  };
  projects.set(project.id, project);
  return { status: 201, body: project };
};

// ─── GET /projects/:id ────────────────────────────────────────────────────────

export const getProject: RouteHandler = async (req) => {
  const project = projects.get(req.query["id"]);
  if (!project) return { status: 404, body: { error: "Project not found" } };
  return { status: 200, body: project };
};

// ─── PUT /projects/:id ────────────────────────────────────────────────────────

export const updateProject: RouteHandler = async (req) => {
  const project = projects.get(req.query["id"]);
  if (!project) return { status: 404, body: { error: "Project not found" } };

  const data = req.body as UpdateProjectBody;
  if (!data) return { status: 400, body: { error: "Request body is required" } };

  if (data.name !== undefined) {
    if (typeof data.name !== "string" || !data.name.trim()) {
      return { status: 400, body: { error: "name must be a non-empty string" } };
    }
    project.name = data.name.trim();
  }

  if (data.description !== undefined) {
    if (typeof data.description !== "string") {
      return { status: 400, body: { error: "description must be a string" } };
    }
    project.description = data.description.trim();
  }

  projects.set(project.id, project);
  return { status: 200, body: project };
};

// ─── DELETE /projects/:id ─────────────────────────────────────────────────────

export const deleteProject: RouteHandler = async (req) => {
  const id = req.query["id"];
  if (!projects.has(id)) return { status: 404, body: { error: "Project not found" } };
  projects.delete(id);
  return { status: 200, body: { message: "Project deleted" } };
};

// ─── POST /projects/:id/members ───────────────────────────────────────────────

export const addMember: RouteHandler = async (req) => {
  const project = projects.get(req.query["id"]);
  if (!project) return { status: 404, body: { error: "Project not found" } };

  const data = req.body as AddMemberBody;
  if (!data || typeof data.userId !== "string" || !data.userId.trim()) {
    return { status: 400, body: { error: "userId is required" } };
  }

  const userId = data.userId.trim();
  if (!users.has(userId)) {
    return { status: 404, body: { error: "User not found" } };
  }

  if (project.memberIds.includes(userId)) {
    return { status: 409, body: { error: "User is already a member of this project" } };
  }

  project.memberIds.push(userId);
  projects.set(project.id, project);
  return { status: 200, body: project };
};

// ─── DELETE /projects/:id/members ─────────────────────────────────────────────

export const removeMember: RouteHandler = async (req) => {
  const project = projects.get(req.query["id"]);
  if (!project) return { status: 404, body: { error: "Project not found" } };

  const data = req.body as AddMemberBody;
  if (!data || typeof data.userId !== "string" || !data.userId.trim()) {
    return { status: 400, body: { error: "userId is required" } };
  }

  const userId = data.userId.trim();
  const idx = project.memberIds.indexOf(userId);
  if (idx === -1) {
    return { status: 404, body: { error: "User is not a member of this project" } };
  }

  project.memberIds.splice(idx, 1);
  projects.set(project.id, project);
  return { status: 200, body: project };
};

import { tasks, projects, users, newId, createNotification, notifyProjectMembers } from "../store.js";
import type {
  RouteHandler,
  CreateTaskBody,
  UpdateTaskBody,
  UpdateStatusBody,
  AssignTaskBody,
  TaskStatus,
} from "../types.js";
import { VALID_TRANSITIONS } from "../types.js";

// ─── GET /tasks ───────────────────────────────────────────────────────────────

export const listTasks: RouteHandler = async (req) => {
  const { projectId } = req.query;
  let result = Array.from(tasks.values());
  if (projectId) {
    result = result.filter((t) => t.projectId === projectId);
  }
  return { status: 200, body: result };
};

// ─── POST /tasks ──────────────────────────────────────────────────────────────

export const createTask: RouteHandler = async (req) => {
  const data = req.body as CreateTaskBody;

  if (!data || typeof data.title !== "string" || !data.title.trim()) {
    return { status: 400, body: { error: "title is required" } };
  }
  if (typeof data.description !== "string") {
    return { status: 400, body: { error: "description is required" } };
  }
  if (typeof data.projectId !== "string" || !data.projectId.trim()) {
    return { status: 400, body: { error: "projectId is required" } };
  }

  const project = projects.get(data.projectId.trim());
  if (!project) {
    return { status: 404, body: { error: "Project not found" } };
  }

  let assigneeId: string | null = null;
  if (data.assigneeId !== undefined && data.assigneeId !== null) {
    if (!users.has(data.assigneeId)) {
      return { status: 404, body: { error: "Assignee user not found" } };
    }
    assigneeId = data.assigneeId;
  }

  const task = {
    id: newId(),
    title: data.title.trim(),
    description: data.description.trim(),
    status: "todo" as TaskStatus,
    assigneeId,
    projectId: data.projectId.trim(),
  };
  tasks.set(task.id, task);

  // Notify assignee if set
  if (assigneeId) {
    const assignee = users.get(assigneeId)!;
    createNotification(
      assigneeId,
      `You have been assigned to task "${task.title}" in project "${project.name}"`,
      "task_assigned"
    );
  }

  return { status: 201, body: task };
};

// ─── GET /tasks/:id ───────────────────────────────────────────────────────────

export const getTask: RouteHandler = async (req) => {
  const task = tasks.get(req.query["id"]);
  if (!task) return { status: 404, body: { error: "Task not found" } };
  return { status: 200, body: task };
};

// ─── PUT /tasks/:id ───────────────────────────────────────────────────────────

export const updateTask: RouteHandler = async (req) => {
  const task = tasks.get(req.query["id"]);
  if (!task) return { status: 404, body: { error: "Task not found" } };

  const data = req.body as UpdateTaskBody;
  if (!data) return { status: 400, body: { error: "Request body is required" } };

  if (data.title !== undefined) {
    if (typeof data.title !== "string" || !data.title.trim()) {
      return { status: 400, body: { error: "title must be a non-empty string" } };
    }
    task.title = data.title.trim();
  }

  if (data.description !== undefined) {
    if (typeof data.description !== "string") {
      return { status: 400, body: { error: "description must be a string" } };
    }
    task.description = data.description.trim();
  }

  tasks.set(task.id, task);
  return { status: 200, body: task };
};

// ─── DELETE /tasks/:id ────────────────────────────────────────────────────────

export const deleteTask: RouteHandler = async (req) => {
  const id = req.query["id"];
  if (!tasks.has(id)) return { status: 404, body: { error: "Task not found" } };
  tasks.delete(id);
  return { status: 200, body: { message: "Task deleted" } };
};

// ─── PUT /tasks/:id/status ────────────────────────────────────────────────────

export const updateTaskStatus: RouteHandler = async (req) => {
  const task = tasks.get(req.query["id"]);
  if (!task) return { status: 404, body: { error: "Task not found" } };

  const data = req.body as UpdateStatusBody;
  if (!data || typeof data.status !== "string") {
    return { status: 400, body: { error: "status is required" } };
  }

  const newStatus = data.status as TaskStatus;
  const allowed = VALID_TRANSITIONS[task.status];

  if (!allowed) {
    return { status: 400, body: { error: `Unknown current status: ${task.status}` } };
  }

  if (!allowed.includes(newStatus)) {
    return {
      status: 422,
      body: {
        error: `Invalid status transition from "${task.status}" to "${newStatus}". Allowed: [${allowed.join(", ") || "none"}]`,
      },
    };
  }

  const previousStatus = task.status;
  task.status = newStatus;
  tasks.set(task.id, task);

  // Notify project members about status change
  const project = projects.get(task.projectId);
  if (project) {
    notifyProjectMembers(
      task.projectId,
      null, // notify everyone including actor for status changes
      `Task "${task.title}" status changed from "${previousStatus}" to "${newStatus}" in project "${project.name}"`,
      "status_changed"
    );

    // Also notify assignee if they're not a member
    if (task.assigneeId && !project.memberIds.includes(task.assigneeId)) {
      createNotification(
        task.assigneeId,
        `Task "${task.title}" status changed from "${previousStatus}" to "${newStatus}"`,
        "status_changed"
      );
    }
  }

  return { status: 200, body: task };
};

// ─── PUT /tasks/:id/assign ────────────────────────────────────────────────────

export const assignTask: RouteHandler = async (req) => {
  const task = tasks.get(req.query["id"]);
  if (!task) return { status: 404, body: { error: "Task not found" } };

  const data = req.body as AssignTaskBody;
  if (data === null || data === undefined || !("userId" in data)) {
    return { status: 400, body: { error: "userId is required (use null to unassign)" } };
  }

  const { userId } = data;

  if (userId !== null) {
    if (typeof userId !== "string" || !userId.trim()) {
      return { status: 400, body: { error: "userId must be a non-empty string or null" } };
    }
    if (!users.has(userId)) {
      return { status: 404, body: { error: "User not found" } };
    }
  }

  const previousAssigneeId = task.assigneeId;
  task.assigneeId = userId;
  tasks.set(task.id, task);

  const project = projects.get(task.projectId);
  const projectName = project ? project.name : "Unknown Project";

  // Notify newly assigned user
  if (userId && userId !== previousAssigneeId) {
    createNotification(
      userId,
      `You have been assigned to task "${task.title}" in project "${projectName}"`,
      "task_assigned"
    );
  }

  return { status: 200, body: task };
};

import { comments, tasks, users, newId, createNotification, projects } from "../store.js";
import type { RouteHandler, CreateCommentBody } from "../types.js";

// ─── GET /comments ────────────────────────────────────────────────────────────

export const listComments: RouteHandler = async (req) => {
  const { taskId } = req.query;
  let result = Array.from(comments.values());
  if (taskId) {
    result = result.filter((c) => c.taskId === taskId);
  }
  return { status: 200, body: result };
};

// ─── POST /comments ───────────────────────────────────────────────────────────

export const createComment: RouteHandler = async (req) => {
  const data = req.body as CreateCommentBody;

  if (!data || typeof data.taskId !== "string" || !data.taskId.trim()) {
    return { status: 400, body: { error: "taskId is required" } };
  }
  if (typeof data.authorId !== "string" || !data.authorId.trim()) {
    return { status: 400, body: { error: "authorId is required" } };
  }
  if (typeof data.body !== "string" || !data.body.trim()) {
    return { status: 400, body: { error: "body is required" } };
  }

  const task = tasks.get(data.taskId.trim());
  if (!task) return { status: 404, body: { error: "Task not found" } };

  const author = users.get(data.authorId.trim());
  if (!author) return { status: 404, body: { error: "Author user not found" } };

  const comment = {
    id: newId(),
    taskId: data.taskId.trim(),
    authorId: data.authorId.trim(),
    body: data.body.trim(),
    createdAt: new Date().toISOString(),
  };
  comments.set(comment.id, comment);

  // ── Notifications ──────────────────────────────────────────────────────────
  const project = projects.get(task.projectId);
  const projectName = project ? project.name : "Unknown Project";

  // Set of users already notified to avoid duplicates
  const notified = new Set<string>();

  // Notify task assignee (if different from author)
  if (task.assigneeId && task.assigneeId !== comment.authorId) {
    createNotification(
      task.assigneeId,
      `${author.name} commented on task "${task.title}" (assigned to you) in project "${projectName}"`,
      "comment_added"
    );
    notified.add(task.assigneeId);
  }

  // Notify project members (except author and already notified users)
  if (project) {
    for (const memberId of project.memberIds) {
      if (memberId !== comment.authorId && !notified.has(memberId)) {
        createNotification(
          memberId,
          `${author.name} commented on task "${task.title}" in project "${projectName}"`,
          "comment_added"
        );
        notified.add(memberId);
      }
    }
  }

  return { status: 201, body: comment };
};

// ─── GET /comments/:id ────────────────────────────────────────────────────────

export const getComment: RouteHandler = async (req) => {
  const comment = comments.get(req.query["id"]);
  if (!comment) return { status: 404, body: { error: "Comment not found" } };
  return { status: 200, body: comment };
};

// ─── DELETE /comments/:id ─────────────────────────────────────────────────────

export const deleteComment: RouteHandler = async (req) => {
  const id = req.query["id"];
  if (!comments.has(id)) return { status: 404, body: { error: "Comment not found" } };
